// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;

import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Explain-plan output for the GH-6193 window function and magic-property (tuple function) algebra nodes: the plan text
 * names the nodes and the function IRIs, and repeated explanations of the same query at the same level are identical,
 * so the output is stable enough to snapshot.
 */
public class ExtensionFunctionExplainSnapshotTest {

	private static final String PREFIXES = "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX winf: <http://rdf4j.org/function/window#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static final String WINDOW_QUERY = PREFIXES
			+ "SELECT ?x (winf:rank(winf:partitionBy(?g), winf:orderBy(winf:desc(?n))) AS ?rank)"
			+ " (winf:sum(?n, winf:orderBy(?x), winf:rows(-1, 0)) AS ?running)"
			+ " WHERE { ?x ex:n ?n ; ex:g ?g } ORDER BY ?x";

	private static final String MAGIC_PROPERTY_QUERY = PREFIXES
			+ "SELECT ?x ?tag WHERE { ?x ex:s ?s . (?s \",\") strf:split (?tag) } ORDER BY ?x ?tag";

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:a ex:n 3 ; ex:g ex:one ; ex:s \"alpha,beta\" .\n"
				+ "ex:b ex:n 10 ; ex:g ex:one ; ex:s \"gamma\" .\n"
				+ "ex:c ex:n 6 ; ex:g ex:two ; ex:s \"delta,eps\" .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	@Test
	void windowNodesAppearInUnoptimizedAndOptimizedPlans() {
		for (Explanation.Level level : new Explanation.Level[] { Explanation.Level.Unoptimized,
				Explanation.Level.Optimized }) {
			String plan = explain(WINDOW_QUERY, level);
			assertThat(plan).as(level + " plan")
					.contains("Window")
					.contains("WindowFunctionCall (http://rdf4j.org/function/window#rank")
					.contains("WindowFunctionCall (http://rdf4j.org/function/window#sum")
					.contains("frame=");
		}
	}

	@Test
	void tupleFunctionNodeAppearsInOptimizedPlan() {
		String unoptimized = explain(MAGIC_PROPERTY_QUERY, Explanation.Level.Unoptimized);
		// the parser leaves the magic property as a statement pattern; the optimizer rewrites it into a tuple function
		assertThat(unoptimized).doesNotContain("TupleFunctionCall");
		String optimized = explain(MAGIC_PROPERTY_QUERY, Explanation.Level.Optimized);
		assertThat(optimized).contains("TupleFunctionCall (http://rdf4j.org/function/string#split)");
	}

	@Test
	void explainOutputIsStableAcrossRepeatedExplanations() {
		for (String query : new String[] { WINDOW_QUERY, MAGIC_PROPERTY_QUERY }) {
			for (Explanation.Level level : new Explanation.Level[] { Explanation.Level.Unoptimized,
					Explanation.Level.Optimized }) {
				// the same prepared query explains identically ...
				try (RepositoryConnection conn = repository.getConnection()) {
					TupleQuery tupleQuery = conn.prepareTupleQuery(query);
					assertThat(tupleQuery.explain(level).toString()).as(level + " plan of\n" + query)
							.isEqualTo(tupleQuery.explain(level).toString());
				}
				// ... and a fresh parse differs only in the generated anonymous variable names, which carry a
				// per-parse unique suffix and therefore have to be masked before snapshotting
				String first = maskAnonymousVariables(explain(query, level));
				String second = maskAnonymousVariables(explain(query, level));
				assertThat(second).as(level + " plan of\n" + query).isEqualTo(first);
			}
		}
	}

	private static String maskAnonymousVariables(String plan) {
		return plan.replaceAll("_anon_[A-Za-z0-9_]+", "_anon_");
	}

	private static String explain(String query, Explanation.Level level) {
		try (RepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(query);
			return tupleQuery.explain(level).toString();
		}
	}
}
